vec2 dither_uv = uv_orig*uTexSize.xy*texsize_noise_lq.zw * 1.2 // makes the graininess of the fur
// 0.5 (very raw) - 3.0 (fine leather)
+ rand_frame.xy;    // needs to be set to keep an overall randomness
