dy = ( GetBlur1(uv+vec2( 0.0 , 1.0 )*d)-GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
float grad = length(vec2(dx.x,dy.x));
ret = mix( vec3(0.5,0.4,0.6)*base.x*emboss.x,
vec3( 8.0 , 5.0 , 2.0 )*grad,
grad*4.2
);
ret = mix(ret,4.0 * ret,GetPixel(uv).y*0.5-GetBlur1(uv).z*0.3*vec3(0.3, 1.0 , 1.0));
grad = length(vec2(dx.z,dy.z));
ret = mix(ret, vec3( 2.0 , 2.0 , 0.0), grad*0.7);
}
  fragColor = vec4(ret, 1.0);
}

